                # CLI runs under `bun` (not node), so install bun first if it's
                # missing. npm wrapped through socket.dev per project policy.
                echo "[bromure-ac] omp not found — installing bun + @oh-my-pi/pi-coding-agent…"
                if ! command -v bun >/dev/null 2>&1; then
                    curl -fsSL https://bun.sh/install | bash >>/tmp/bromure-tool-install.log 2>&1 || true
                    [ -d "$HOME/.bun/bin" ] && export PATH="$HOME/.bun/bin:$PATH"
                fi
                if npx --yes @socketsecurity/cli npm install -g --silent @oh-my-pi/pi-coding-agent \\
                        >>/tmp/bromure-tool-install.log 2>&1; then
                    echo "[bromure-ac] installed @oh-my-pi/pi-coding-agent"
                    return 0
                fi
                echo "[bromure-ac] install failed (see /tmp/bromure-tool-install.log)"
                return 1
                ;;
            grok)
                # Grok ships via x.ai's shell installer (not npm). Fallback
                # only — normally baked into the base image. The installer
                # drops it under ~/.grok/bin, so add that to PATH.
                echo "[bromure-ac] grok not found — installing via x.ai…"
                if curl -fsSL https://x.ai/cli/install.sh | bash >>/tmp/bromure-tool-install.log 2>&1; then
                    [ -d "$HOME/.grok/bin" ] && export PATH="$HOME/.grok/bin:$PATH"
                    echo "[bromure-ac] installed grok"
                    return 0
                fi
                echo "[bromure-ac] install failed (see /tmp/bromure-tool-install.log)"
                return 1
                ;;
            *)
                return 1
                ;;
        esac
    }

    # Make `<agent> update` actually take effect — ON DEMAND only, so bandwidth
    # is spent solely when the user updates (nothing is ever pre-fetched). The
    # agents are baked as ROOT installs the workspace user can't update in place,
    # but each one's own updater already writes to a user-owned, PATH-first dir
    # (~/.npm-global, ~/.grok/bin — the latter added to PATH above) and works.
    # Two need a small nudge; the rest (codex, omp) already do the right thing:
    #
    #  • claude: `claude update` updates the npm-global build in place and nags
    #    about a "native vs npm-global" mismatch. Redirect it to a clean NATIVE
    #    install in ~/.local/bin (first on PATH). Every other claude call passes
    #    straight through, so this only downloads when the user runs an update.
    claude() {
        case "$1" in
            update|upgrade)
                command claude install stable
                hash -r 2>/dev/null || true ;;
            *) command claude "$@" ;;
        esac
    }
    #  • kimi: `kimi update` refuses an npm layout ("unsupported package manager
    #    or layout") and tells you to npm-install — do exactly that, into the
    #    user-owned ~/.npm-global (first on PATH) so it takes effect. Wrapped
    #    through socket.dev per project policy. Other kimi calls pass through.
    kimi() {
        case "$1" in
            update|upgrade)
                npx --yes @socketsecurity/cli npm install -g @moonshot-ai/kimi-code@latest
                hash -r 2>/dev/null || true ;;
            *) command kimi "$@" ;;
        esac
    }
    #  • grok: keep the approval mode Grok's OWN config names. Grok ≥ 1.0.46
    #    also obeys Claude Code's ~/.claude/settings.json permissions.defaultMode
    #    (its "Claude-compatible settings"), which Bromure seeds to "auto" for
    #    Claude — so in a workspace with both, a Grok whose config.toml says
    #    [ui] permission_mode = "ask" ran shell commands and writes unasked.
    #    When Grok's config asks (or names no mode), pin that on the command
    #    line (`--permission-mode default` = Ask; the CLI wins over every
    #    config file). Any other mode the user chose, an explicit mode flag,
    #    a headless -p run and the subcommands pass straight through. Only
    #    ever stricter, never looser.
    grok() {
        case "${1:-}" in
            agent|clone|completions|cursor-worker|dashboard|doctor|du|disk-usage|export|help|inspect|leader|login|logout|mcp|memory|models|plugin|sessions|setup|trace|update|upgrade|usage|version|v|worktree|wrap)
                command grok "$@"; return ;;
        esac
        case " $* " in
            *" --always-approve "*|*" --yolo "*|*" --permission-mode "*|*" --permission-mode="*|*" -p "*|*" --single "*|*" -h "*|*" --help "*|*" -v "*|*" --version "*)
                command grok "$@"; return ;;
        esac
        _bg_mode=$(awk '/^\\[/{ui=($0 ~ /^\\[ui\\][[:space:]]*$/)} ui && /^[[:space:]]*(permission_mode|approval_mode)[[:space:]]*=/{sub(/^[^=]*=[[:space:]]*"/,""); sub(/".*/,""); print; exit}' "$HOME/.grok/config.toml" 2>/dev/null)
        case "${_bg_mode:-ask}" in
            ask|default) command grok --permission-mode default "$@" ;;
            *) command grok "$@" ;;
        esac
    }

    # Auto-launch the agent on the FIRST interactive shell of this VM
    # session only. Subsequent kitty tabs / new windows / nested shells
    # all skip the launch and land at plain bash. The marker lives in
    # /tmp so it resets across reboots.
    _bromure_marker=/tmp/.bromure-ac-agent-launched
    # Auto-launch the agent ONLY in a registration VM (BROMURE_AC_REGISTER=1),
    # so a throwaway login VM kicks off `claude`/`codex` automatically. Normal
    # sessions intentionally land at a plain shell — the user starts the agent
    # themselves. Gated to once per boot by the marker; `-t 1` (interactive
    # terminal) is used instead of `$SHLVL=1` because the kitty's bash runs at
    # SHLVL 2 (login shell → startx → openbox → kitty adds a level).
    # Worktree tab: the host opens this window with BROMURE_AC_WT_TOOL set (see
    # `worktree-create`). Run that tool here — this branch runs regardless of
    # the primary-tab marker, so a worktree sub-agent always starts even though
    # the first tab already claimed the marker. All the env/MCP/token setup
    # above has already run for this interactive shell.
    if [ -n "${BROMURE_AC_WT_TOOL:-}" ] && [ -t 1 ]; then
        _wt_tool="$BROMURE_AC_WT_TOOL"; unset BROMURE_AC_WT_TOOL
        # Pin the agent's start dir to the checkout root the guest agent
        # chose. tmux already opens the window there (-c), but the agent
        # must never inherit a drifted $PWD — an agent started in a
        # subfolder scopes itself to that subfolder.
        _wt_dir="${BROMURE_AC_WT_DIR:-}"; unset BROMURE_AC_WT_DIR
        if [ -n "$_wt_dir" ] && [ -d "$_wt_dir" ]; then
            cd -- "$_wt_dir" 2>/dev/null || true
        fi
        # Extra CLI flags for THIS launch only, decided host-side by agentd
        # (empty for manual worktrees; the unattended-automation path passes
        # each tool's skip-confirmation flag so the "trust this folder" /
        # permission prompt can't hang the run). Captured and unset before the
        # tool runs, so it never leaks to the agent, a subshell, or the next
        # command — and .bashrc holds no knowledge of what the flags mean.
        # Flags have no spaces, so $_wt_flags is left unquoted to word-split
        # (empty → nothing).
        _wt_flags="${BROMURE_AC_WT_FLAGS:-}"; unset BROMURE_AC_WT_FLAGS
        if ! command -v "$_wt_tool" >/dev/null 2>&1; then
            _bromure_install_tool "$_wt_tool" || true
            hash -r 2>/dev/null || true
        fi
        # Resuming a Claude session that never got a conversation in this
        # folder: `--continue` would die on "No conversation found to
        # continue" — start it fresh instead. (Claude keeps a folder's
        # conversations under its path with every non-alphanumeric as "-".)
        case " $_wt_flags " in *" --continue "*)
            if [ "$_wt_tool" = "claude" ] && ! ls "$HOME/.claude/projects/$(pwd | sed 's/[^A-Za-z0-9]/-/g')"/*.jsonl >/dev/null 2>&1; then
                _wt_flags=$(printf '%s' " $_wt_flags " | sed 's/ --continue / /')
            fi ;;
        esac
        # Type $1 into this tab's agent once it is up, with a beat for its
        # input box to draw — a fallback for a launch that hands Kimi its
        # opening message here (the host types board messages itself).
        # "Up" is read from the pane's process list: an agent started from
        # this file runs in the shell's process group, so tmux's
        # pane_current_command keeps naming bash while it runs.
        _bromure_type_when_up() {
            _tw_pane="${TMUX_PANE:-}"
            [ -n "$_tw_pane" ] || return 0
            _tw_tty=$(tmux display-message -p -t "$_tw_pane" '#{pane_tty}' 2>/dev/null)
            _tw_tty="${_tw_tty#/dev/}"
            _tw_i=0
            while [ "$_tw_i" -lt 180 ]; do
                sleep 1; _tw_i=$((_tw_i + 1))
                ps -t "$_tw_tty" -o args= 2>/dev/null | grep -v -E '^-?(bash|sh)( |$)' \\
                    | grep -q -E '(^|[^A-Za-z0-9])kimi([^A-Za-z]|$)' || continue
                sleep 4
                tmux send-keys -t "$_tw_pane" -l -- "$1" && sleep 1 \\
                    && tmux send-keys -t "$_tw_pane" Enter
                return 0
            done
        }
        _wt_interactive="${BROMURE_AC_WT_INTERACTIVE:-}"; unset BROMURE_AC_WT_INTERACTIVE
        # Kimi's approval mode for an interactive launch: the workspace's
        # setting, staged by the host (Never Ask = --auto, the default; Ask
        # When Needed = --yolo). Without one Kimi starts in "Always Ask" and
        # prompts for every command and MCP tool. A launch whose flags already
        # carry a mode (the host's own session launches) keeps it — Kimi
        # refuses --auto and --yolo together.
        _kimi_mode=--auto
        case "$(cat /mnt/bromure-meta/kimi-approvals 2>/dev/null)" in --yolo) _kimi_mode=--yolo ;; esac
        case " $_wt_flags " in *" --auto "*|*" --yolo "*) _kimi_mode= ;; esac
        if command -v "$_wt_tool" >/dev/null 2>&1; then
            # Say "in worktree" only for a linked git worktree (its git dir
            # differs from the shared common dir) — a plain session runs in
            # the folder itself.
            _wt_where=
            if [ "$(git rev-parse --path-format=absolute --git-dir 2>/dev/null)" != \\
                 "$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null)" ]; then
                _wt_where=' in worktree'
            fi
            printf '\\033[2m[bromure-ac] starting %s%s…\\033[0m\\n' "$_wt_tool" "$_wt_where"
            if [ "$_wt_tool" = "kimi" ] && [ -n "$_wt_interactive" ]; then
                # A coding-board task (agentd sets BROMURE_AC_WT_INTERACTIVE):
                # Kimi must stay in its TUI so review feedback and the
                # landing brief reach the SAME conversation — the one-shot
                # --prompt run exits and leaves a bare shell, where typed
                # feedback ran as bash commands. $_kimi_mode is the
                # workspace's approval mode (refused with --prompt, fine
                # here). The host types the
                # opening message in once the TUI is up; a prompt handed over
                # here anyway is typed by the fallback above. -c (a
                # resume) stays in $_wt_flags.
                if [ -n "${BROMURE_AC_WT_PROMPT:-}" ]; then
                    _wt_prompt=$(printf '%s' "$BROMURE_AC_WT_PROMPT" | base64 -d 2>/dev/null)
                    unset BROMURE_AC_WT_PROMPT
                    ( _bromure_type_when_up "$_wt_prompt" </dev/null >/dev/null 2>&1 & )
                fi
                "$_wt_tool" $_wt_flags $_kimi_mode
                _wt_rc=$?
            elif [ -n "${BROMURE_AC_WT_PROMPT:-}" ]; then
                _wt_prompt=$(printf '%s' "$BROMURE_AC_WT_PROMPT" | base64 -d 2>/dev/null)
                unset BROMURE_AC_WT_PROMPT
                if [ "$_wt_tool" = "kimi" ]; then
                    # kimi refuses positional prompts outright ("unknown
                    # command"); its --prompt one-shot mode is the only way to
                    # hand it an initial task, runs fully autonomously by
                    # design, and ERRORS if combined with --yolo/--auto — so
                    # the flags are dropped. The = form binds a prompt that
                    # starts with "-" unambiguously. The process exits when
                    # the turn completes — its own Stop hook reports done,
                    # and so does the clean-exit path below.
                    # A landing hand-off resumes kimi's own conversation
                    # (-c, the one flag kept).
                    case " $_wt_flags " in
                        *" -c "*) "$_wt_tool" -c --prompt="$_wt_prompt" ;;
                        *) "$_wt_tool" --prompt="$_wt_prompt" ;;
                    esac
                    _wt_rc=$?
                    # One-shot mode exits when the turn ends, dropping to this
                    # shell. Point the way back in — the session is still there.
                    [ "$_wt_rc" -eq 0 ] && printf \\
                        '\\033[2m[bromure-ac] run finished — `kimi -c` resumes it interactively\\033[0m\\n'
                elif [ "$_wt_tool" = "omp" ]; then
                    # omp needs an explicit --model to run non-interactively;
                    # the host stages the resolved model (provider default or
                    # local model) in the meta share. --auto-approve (in
                    # $_wt_flags) skips tool prompts; the TUI runs the seeded
                    # message and auto-approves. "--" ends option parsing so a
                    # prompt starting with "-" is the positional message.
                    _omp_model=""
                    [ -r /mnt/bromure-meta/omp-model ] \\
                        && _omp_model=$(cat /mnt/bromure-meta/omp-model 2>/dev/null)
                    if [ -n "$_omp_model" ]; then
                        "$_wt_tool" $_wt_flags --model "$_omp_model" -- "$_wt_prompt"
                    else
                        "$_wt_tool" $_wt_flags -- "$_wt_prompt"
                    fi
                    _wt_rc=$?
                else
                    # "--" ends option parsing, so the prompt is unambiguously the
                    # positional argument. Without it a prompt whose first character
                    # is "-" — an automation written as a bullet list, say — is read
                    # as a flag by the agent's own parser, which dies before the run
                    # starts ("error: unknown option '- Generate a report…'").
                    "$_wt_tool" $_wt_flags -- "$_wt_prompt"
                    _wt_rc=$?
                fi
            elif [ "$_wt_tool" = "kimi" ]; then
                # An interactive Kimi with no opening message on its command
                # line (a branch session: the host types it once the TUI is
                # up) — in the workspace's approval mode too.
                "$_wt_tool" $_wt_flags $_kimi_mode
                _wt_rc=$?
            else
                "$_wt_tool" $_wt_flags
                _wt_rc=$?
            fi
            # A nonzero exit means the agent DIED (bad flag, config error,
            # crash) rather than finishing — flag the tab needs-input so the
            # board card turns red instead of sitting "in progress" forever;
            # the error is on screen in this terminal. A clean exit means the
            # agent is genuinely finished, whatever the tool: report done so
            # the tab's dot settles even for agents with no completion hook.
            # (The automation engine still only ACTS on a done from a
            # hook-driven agent — see Profile.Tool.hasReliableDoneSignal.)
            if [ "$_wt_rc" -ne 0 ]; then
                printf '\\033[31m[bromure-ac] %s exited with status %s\\033[0m\\n' "$_wt_tool" "$_wt_rc"
                sh "$HOME/.bromure/agent-status.sh" needsInput 2>/dev/null || true
            else
                sh "$HOME/.bromure/agent-status.sh" done 2>/dev/null || true
            fi
        else
            # Not installed (and the install above failed): the same marker
            # the host's launch watch looks for, so it fails fast.
            printf '\\033[31m[bromure-ac] %s exited with status 127 (command not found)\\033[0m\\n' "$_wt_tool"
            sh "$HOME/.bromure/agent-status.sh" needsInput 2>/dev/null || true
        fi
        unset _wt_tool _wt_prompt _wt_flags _wt_dir _wt_interactive _kimi_mode
    fi

    if [ "$BROMURE_AC_REGISTER" = "1" ] \\
       && [ -t 1 ] \\
       && [ ! -e "$_bromure_marker" ] \\
       && [ -n "$BROMURE_AC_TOOL" ]; then
        if ! command -v "$BROMURE_AC_TOOL" >/dev/null 2>&1; then
            _bromure_install_tool "$BROMURE_AC_TOOL" || true
            # Re-source PATH-affecting bits in case install added bins.
            hash -r 2>/dev/null || true
        fi
        if command -v "$BROMURE_AC_TOOL" >/dev/null 2>&1; then
            : > "$_bromure_marker"
            # Visible breadcrumb so a slow-starting agent doesn't
            # look like a hung black terminal — particularly after
            # a reboot, when /tmp is fresh and this auto-launch
            # path runs again from scratch.
            printf '\\033[2m[bromure-ac] starting %s…\\033[0m\\n' "$BROMURE_AC_TOOL"
            # kimi's TUI does NOT prompt for login on first run (the user
            # would have to type /login); its `kimi login` subcommand drives
            # the device-code flow directly, which is exactly what a
            # registration VM exists for.
            # Each CLI's login subcommand goes straight to the browser
            # hand-off — no wizard in between (see launchRegistrationAgentIfNeeded).
            case "$BROMURE_AC_TOOL" in
                claude) claude auth login --claudeai ;;
                codex)  codex login ;;
                grok)   grok login ;;
                kimi)   kimi login ;;
                *)      "$BROMURE_AC_TOOL" ;;
            esac
        fi
    fi
    unset _bromure_marker

    # User customizations.
    [ -f "$HOME/.bashrc.local" ] && . "$HOME/.bashrc.local"
    """

    // @port-skip linux-only: generated (ProfileStore.bashrcLocalSeed)
    static let bashrcLocalSeed = """
    # ~/.bashrc.local — your customizations live here. Anything in this
    # file is sourced at the end of the managed .bashrc and is preserved
    # across Bromure AC updates.
    #
    # Examples:
    #   alias ll='ls -lah'
    #   export EDITOR=nvim
    """

    // @port-skip linux-only: generated (ProfileStore.bashProfileContent)
    static let bashProfileContent = #"""
    # Apply per-profile hostname BEFORE startx — see comment above.
    if [ -r /mnt/bromure-meta/hostname.txt ]; then
        NEW_HOST=$(head -1 /mnt/bromure-meta/hostname.txt | tr -d '[:space:]')
        # Every terminal is a login shell too: only the first one (tty1, at
        # boot) has anything to change. sudo -n everywhere in this file: under
        # the strict sandbox the agent user has no sudo, and a plain sudo
        # prompts for a password on the terminal (>/dev/null doesn't hide
        # the prompt, which goes to the tty).
        if [ -n "$NEW_HOST" ] && [ "$(hostname)" != "$NEW_HOST" ]; then
            # /etc/hosts first, so subsequent sudo calls can resolve.
            NEW_HOSTS=$(mktemp 2>/dev/null || echo /tmp/hosts.new)
            {
                printf '127.0.0.1\tlocalhost %s\n'  "$NEW_HOST"
                printf '::1\tlocalhost %s\n'         "$NEW_HOST"
                printf '127.0.1.1\t%s\n'             "$NEW_HOST"
                printf '\n# Bromure AC: managed at session boot.\n'
            } > "$NEW_HOSTS"
            sudo -n install -m 644 "$NEW_HOSTS" /etc/hosts >/dev/null 2>&1 || true
            rm -f "$NEW_HOSTS"
            sudo -n hostname "$NEW_HOST" >/dev/null 2>&1 || true
            echo "$NEW_HOST" | sudo -n tee /etc/hostname >/dev/null 2>&1 || true
        fi
    fi

    # Headless boot (plan phase 3): on tty1 (the agetty autologin terminal)
    # bootstrap the bromure-agentd systemd unit and hand the session to it —
    # X11/kitty stay on disk but never start. Rewritten whenever the marker
    # line is missing, so existing images converge without a rebuild (agentd's
    # task_fix_systemd_unit is the twin for images that don't reboot — keep
    # the unit text byte-identical with _UNIT_CONTENT there). KillMode=process
    # is the load-bearing line: the tmux server and every agent in it live in
    # this service's cgroup, and the default control-group kill made the
    # hot-upgrade exit(0) SIGTERM the whole session and stall the respawn for
    # TimeoutStopSec (default 90s) — a frozen, then emptied, workspace.
    # StartLimitIntervalSec=0: the daemon must respawn forever; the default
    # 5-in-10s limit permanently failed the unit on a crash loop even after
    # the host restaged a fixed source.
    if [ "$(tty)" = "/dev/tty1" ] && [ -r /mnt/bromure-meta/bromure-agentd.py ]; then
        if ! grep -sq "python3 -s " /etc/systemd/system/bromure-agentd.service; then
            sudo -n tee /etc/systemd/system/bromure-agentd.service >/dev/null <<'UNIT'
    [Unit]
    Description=Bromure guest agent daemon
    After=mnt-bromure\x2dmeta.mount network.target
    StartLimitIntervalSec=0
    ConditionPathExists=/mnt/bromure-meta/bromure-agentd.py
    [Service]
    Type=simple
    User=ubuntu
    ExecStart=/usr/bin/python3 -s /mnt/bromure-meta/bromure-agentd.py
    Restart=always
    RestartSec=1
    KillMode=process
    TimeoutStopSec=5
    [Install]
    WantedBy=multi-user.target
    UNIT
            sudo -n systemctl daemon-reload >/dev/null 2>&1 || true
            sudo -n systemctl enable bromure-agentd.service >/dev/null 2>&1 || true
        fi
        sudo -n systemctl start bromure-agentd.service >/dev/null 2>&1 || true
    fi
    [ -f "$HOME/.bashrc" ] && . "$HOME/.bashrc"
    """#

    // @port-skip linux-only: generated (ProfileStore.profileContent)
    static let profileContent = """
    if [ -n "$BASH_VERSION" ] && [ -f "$HOME/.bashrc" ]; then
        . "$HOME/.bashrc"
    fi
    """

    // @port-skip linux-only: generated (ProfileStore.agentCLIPackages)
    static let agentCLIPackages = [
        "@anthropic-ai/claude-code",
        "@openai/codex",
        "@moonshot-ai/kimi-code",
        "@oh-my-pi/pi-coding-agent",
    ]

    // @port-skip linux-only: generated (the .tmux.conf literal in ProfileStore.populateManagedHome)
    static let tmuxConf = """
        set -g status off
        set -g mouse off
        set -g escape-time 10
        set -g history-limit 100000
        set -g default-terminal "screen-256color"
        set -g window-size latest
        set -g base-index 0
        set -g renumber-windows off
        set -g set-clipboard on
        """
}
